body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: -apple-system, "PingFang SC", sans-serif;
  background: #fff7ed;
  color: #3b2a1a;
}
main { text-align: center; }
#time { font-size: 72px; font-weight: 700; margin: 12px 0 24px; font-variant-numeric: tabular-nums; }
button {
  font-size: 16px;
  padding: 10px 22px;
  margin: 0 6px;
  border: 0;
  border-radius: 999px;
  background: #e8710a;
  color: #fff;
}
#reset { background: #d6c3ad; }

// A 25-minute timer: start, pause, start again.
const time = document.getElementById("time");
const go = document.getElementById("go");
let left = 25 * 60, timer = null;

const show = () => {
  const m = String(Math.floor(left / 60)).padStart(2, "0");
  const s = String(left % 60).padStart(2, "0");
  time.textContent = `${m}:${s}`;
};

go.onclick = () => {
  if (timer) { clearInterval(timer); timer = null; go.textContent = "继续"; return; }
  go.textContent = "暂停";
  timer = setInterval(() => {
    left = Math.max(0, left - 1);
    show();
    if (!left) { clearInterval(timer); timer = null; go.textContent = "开始"; alert("休息一下吧"); }
  }, 1000);
};

document.getElementById("reset").onclick = () => {
  clearInterval(timer); timer = null; left = 25 * 60; go.textContent = "开始"; show();
};
